export async function apiProfileSave(name, options = {}) {
  let agents_data
  if (options.targets && options.targets.length > 0) {
    agents_data = {}
    for (const flag of options.targets) {
      const entry = await captureAgentFull(flag)
      if (entry) agents_data[flag] = entry
    }
  } else {
    agents_data = await captureAllAgents()
  }

  if (Object.keys(agents_data).length === 0) {
    throw new Error('No agent configurations found to save.')
  }

  if (options.dryRun) {
    return { dryRun: true, name, agents: agents_data }
  }

  const profileData = {
    name,
    description: `Saved on ${new Date().toLocaleDateString()}`,
    agents: agents_data,
  }

  await writeProfile(profileData)
  return { name, agents: Object.keys(agents_data).length, profile: profileData }
}
